            return response.Data;
        }

        /// <summary>
        /// Revoke a bank connection
        /// </summary>
        /// <remarks>
        /// Stops access to the bank. Bank fetches stop the moment you ask, even while the bank's confirmation is pending: the consent reads <c>revocation_pending</c>, then <c>revoked</c> once the bank confirms access is terminated, or <c>revocation_failed</c> while the call is retried automatically. <c>consent.ended_by</c> is <c>customer</c>.
        /// <para/>
        /// Revoking does not delete anything: stored accounts, balances and transactions stay readable until <c>consent.retain_until</c>, the retention setting of your application, and nothing is charged. To delete them now, call <c>delete_connection</c>. Repeating the call returns the current state.
        /// <para/>
        /// Needs an API key with the Bank data permission (<c>bank-data</c>): write for this operation, which changes something. A key with full access does not include it: grant it explicitly when you create the key, or the call answers <c>403 bank_data_access_denied</c>.
        /// <para/>
        /// Revoking a connection that was deleted answers <c>200</c> with the deleted connection, so repeating the call is safe.
        /// <para/>
        /// <c>POST /v3/bank/connections/{id}/revoke/</c> (<c>bank.revoke_connection</c>).
        /// Accepts an idempotency key: set <see cref="RequestOptions.IdempotencyKey"/>.
        /// </remarks>
        /// <param name="id">The connection id.</param>
        /// <param name="requestOptions">Per-request overrides of the client options.</param>
        /// <param name="cancellationToken">Cancels the request.</param>
        public async Task<BankConnection> RevokeConnectionAsync(string id, RequestOptions? requestOptions = null, CancellationToken cancellationToken = default)
        {
            var response = await _raw.RevokeConnectionAsync(id, requestOptions, cancellationToken).ConfigureAwait(false);
            return response.Data;
        }

        /// <summary>
        /// Sync transactions (change feed)
        /// </summary>
        /// <remarks>
        /// Returns what changed in a connection's transactions since a <c>cursor</c>: <c>added</c>, <c>modified</c> and <c>removed</c> (with a <c>reason</c>), across all its accounts. An empty cursor returns every current transaction as <c>added</c> and sets <c>reset: true</c>: replace your copy with it instead of adding to it.
        /// <para/>
        /// The first read is a true snapshot. A first read (no cursor, or the read after <c>reset</c>) returns every transaction the connection had when the read started, each exactly once as <c>added</c>, in its current state, even if a sync runs while you page. Changes made while you were paging arrive in the next read from <c>next_cursor</c>: a transaction you already received comes again as <c>modified</c>, and a new one as <c>added</c>. Apply <c>modified</c> as an upsert by <c>id</c>, and ignore a <c>removed</c> id you do not have. All pages of one read reflect the same point in time. Keep paging with <c>page_token</c> while <c>has_more</c> is <c>true</c>, and store <c>next_cursor</c> only after a response with <c>has_more: false</c>. If paging fails midway, restart from the cursor you had stored.
        /// <para/>
        /// The change log is replayable for 90 days. An older cursor answers <c>410 cursor_expired</c> with <c>bootstrap: true</c>: start again from an empty cursor. Stored history is never aged out while the connection exists. A booked pending transaction appears in <c>added</c> and the pending one in <c>removed</c> with <c>reason: pending_booked</c>. Webhook <c>bank.data.updated</c> tells you when to call.
        /// <para/>
        /// Needs an API key with the Bank data permission (<c>bank-data</c>): read for this operation. A key with full access does not include it: grant it explicitly when you create the key, or the call answers <c>403 bank_data_access_denied</c>. A sandbox application reads its Test Bank data with the key alone. A request without an API key (client credentials) is refused on raw data with the same <c>403</c>.
        /// <para/>
        /// <c>GET /v3/bank/connections/{id}/transactions/sync/</c> (<c>bank.sync_transactions</c>).
        /// </remarks>
        /// <param name="id">The connection id.</param>
        /// <param name="parameters">The request parameters.</param>
        /// <param name="requestOptions">Per-request overrides of the client options.</param>
        /// <param name="cancellationToken">Cancels the request.</param>
        public async Task<BankTransactionChanges> SyncTransactionsAsync(string id, BankSyncTransactionsParams? parameters = null, RequestOptions? requestOptions = null, CancellationToken cancellationToken = default)
        {
            var response = await _raw.SyncTransactionsAsync(id, parameters, requestOptions, cancellationToken).ConfigureAwait(false);
            return response.Data;
        }
    }

